async function o(n){if(!n||n.trim().length===0)return[];try{const r=new URL("https://nominatim.openstreetmap.org/search");r.searchParams.append("q",n),r.searchParams.append("format","json"),r.searchParams.append("limit","5");const e=await fetch(r.toString(),{headers:{"User-Agent":"ReactGISApp/1.0"}});if(!e.ok)throw new Error(`Nominatim API error: ${e.status}`);const t=await e.json();if(t&&Array.isArray(t))return t.map(a=>({address:n,lat:parseFloat(a.lat),lng:parseFloat(a.lon),formattedAddress:a.display_name,source:"nominatim",confidence:a.importance?a.importance*10:void 0}))}catch(r){console.error("Nominatim geocoding failed",r)}return[]}async function s(n,r){try{const e=new URL("https://nominatim.openstreetmap.org/reverse");e.searchParams.append("lat",n.toString()),e.searchParams.append("lon",r.toString()),e.searchParams.append("format","json");const t=await fetch(e.toString(),{headers:{"User-Agent":"ReactGISApp/1.0"}});if(!t.ok)throw new Error(`Nominatim API error: ${t.status}`);const a=await t.json();if(a&&a.display_name)return{address:a.display_name,lat:parseFloat(a.lat),lng:parseFloat(a.lon),formattedAddress:a.display_name,source:"nominatim"}}catch(e){console.error("Nominatim reverse geocoding failed",e)}return null}export{o as geocodeAddress,s as reverseGeocode};
